     busy_mode_ = true;
     sendTextMessage(mode_to_command(requested_mode_));
     mysleep7(1000);
     if (requested_mode_.isEmpty() || requested_mode_ == mode_) update_mode (m);
     else {


replace "mysleep7" by "mysleep8"


b) second error: frequency "drift"
-------------------------------

to reproduce
- start SDR program, 7074 kHz, USB-Data
- in wsjtx: use "Fake split" and operate at 300 Hz
- call CQ repeatedly, or repeatedly to TUNE

what happens: one starts with RX=7074.0 and TX=7072.5, but at some point the RX freq jumps
and one has RX=7072.5 and TX=7071.0, later one, another jump to RX=7071.0 and TX=7069.5 etc. etc.
If this happens during a QSO that't the end.

The reason is subtle: if between the "VFO" command (freq change" and the "TRX" command
(go TX) handle_transceiver_update() (in widgets/mainwindow.cpp)  "fires", then at this place

 if (s.frequency () != old_state.frequency () || s.split () != m_splitMode)
   {
     m_splitMode = s.split ();
     if (!s.ptt ())
       {
         m_freqNominal = s.frequency () - m_astroCorrection.rx;  <== HERE IT HAPPENS
         if (old_freqNominal != m_freqNominal)
           {
             m_freqTxNominal = m_freqNominal;
             genCQMsg ();
           }

the frequency drift takes place, by setting m_freqNominal to 7072.5.
This happens if s.frequency() is already at 7072.5 and s.ptt() is still
at FALSE.

I have no clean solution, but if in CITransceiver.cpp in do_frequency()
here

 if (tci_Ready && _power_) {
   if ((rx_frequency_ != requested_rx_frequency_)) {
     busy_rx_frequency_ = true;
     band_change = abs(rx_frequency_.toInt()-requested_rx_frequency_.toInt()) > 1000000;
     const QString cmd = CmdVFO + SmDP + rx_ + SmCM + "0" + SmCM + requested_rx_frequency_ + SmTZ;
     if(f > 100000 && f< 250000000000) sendTextMessage(cmd);
     mysleep7(2000);
     // if (band_change) mysleep7(500);
     band_change2 = abs(rx_frequency_.toInt()-requested_rx_frequency_.toInt()) > 1000000;
     if (!band_change2) update_rx_frequency (f);


the last line is changed to

     if (requested_rx_frequency_ == rx_frequency_) ; // update_rx_frequency (f);

then the frequency change report is delayed and this cures the race condition.



